Title: Problem renaming associations output
Description: So I'm having an issue with the `as` sub-parameter of the `include` parameter to `.findAll`.  I'm using 2.0.0-dev11 + MySQL.

The error I get back is:

```
Possibly unhandled Error: Task (Experiment) is not associated to User!
```

The error occurs in:

```
node_modules/sequelize/lib/dao-factory.js:1812:13
```

So in the code below, if I change `{ include: [{model:Task,as:'Experiment'}]}` to `{ include: Task }` then it works just fine.

But I really want to get the association back in a list named `Experiments` instead of named `Tasks`.

```
var User = sequelize.define('User', { name: Sequelize.STRING });
var Task = sequelize.define('Task', { name: Sequelize.STRING });

Task.belongsTo(User);
User.hasMany(Task);

sequelize.sync({force: true})
  .then(function() {
    return User.create({name:'Rick'});
  })
  .then(function(u) {
    var task = Task.build({name:'Science'});
    return u.addTask(task);
  })
  .then(function() {
    return User.findAll({ include: [{model:Task,as:'Experiment'}]});
  })
  .then(function(users) {
    console.log(JSON.stringify(users, null, 2));
  })
  .then(function() {
    console.log('done');
  });
```


